<template><section class="overflow-hidden rounded-lg border border-gray-200 bg-white dark:border-dark-700 dark:bg-dark-900"><div class="border-b border-gray-200 px-4 py-3 text-sm font-semibold dark:border-dark-700 dark:text-white">Alert lifecycle</div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead><tr class="border-b border-gray-200 text-xs uppercase text-gray-500 dark:border-dark-700"><th class="px-4 py-3">Model</th><th class="px-4 py-3">Domain</th><th class="px-4 py-3">Cause</th><th class="px-4 py-3">Severity</th><th class="px-4 py-3">Status</th></tr></thead><tbody><tr v-for="alert in store.alerts" :key="alert.id" class="border-b border-gray-100 dark:border-dark-800"><td class="px-4 py-3 font-medium dark:text-white">{{ alert.model_route }}</td><td class="px-4 py-3">{{ alert.capability_domain }}</td><td class="px-4 py-3">{{ alert.cause }}</td><td class="px-4 py-3">{{ alert.severity ?? 'P1' }}</td><td class="px-4 py-3"><Status :value="alert.status" /></td></tr></tbody></table></div></section></template><script setup lang="ts">import { onMounted } from 'vue'; import { useRadarStore } from '@/stores/radar'; import Status from './components/Status.vue'; const store = useRadarStore(); onMounted(() => store.loadSection('alerts'));</script>
